#!/usr/bin/env python3
"""Focused regression/type test for the oe-21-kernel FF-A offset fix.

Runs with cwd = a clean checkout of the target with generated.patch applied.
1) Source-level assertions on the patched arch/arm64/kvm/hyp/nvhe/ffa.c.
2) Compiles and runs a C harness that mirrors the exact kernel types and the
   pre-fix vs post-fix guard, using host gcc (LP64, same data model as arm64).
"""
from __future__ import annotations

import os
import subprocess
import sys
from pathlib import Path

FFA = Path("arch/arm64/kvm/hyp/nvhe/ffa.c")
WORK = Path("/workspace/repo/.patch-port/tmp/regression")
WORK.mkdir(parents=True, exist_ok=True)

failures = []


def check(cond: bool, msg: str) -> None:
    print(("PASS: " if cond else "FAIL: ") + msg)
    if not cond:
        failures.append(msg)


# ---- 1. Source-level assertions -------------------------------------------------
src = FFA.read_text()
check("u32 offset, nr_ranges, checked_offset;" in src, "declaration adds checked_offset")
check(
    "check_add_overflow(offset, sizeof(struct ffa_composite_mem_region), &checked_offset)" in src,
    "guard uses check_add_overflow into checked_offset",
)
check("if (fraglen < checked_offset) {" in src, "bound is checked against checked_offset")
check(
    "fraglen < offset + sizeof(struct ffa_composite_mem_region)" not in src,
    "old unchecked bound expression is gone",
)
check("ret = FFA_RET_INVALID_PARAMETERS;" in src, "error path still returns FFA_RET_INVALID_PARAMETERS")

# ---- 2. Behaviour/type harness --------------------------------------------------
c_src = r'''
#include <stdio.h>
#include <stdint.h>

typedef uint32_t u32;

struct ffa_mem_region_addr_range { uint64_t address; u32 pg_cnt; u32 reserved; };
struct ffa_composite_mem_region {
    u32 total_pg_cnt;
    u32 addr_range_cnt;
    uint64_t reserved;
    struct ffa_mem_region_addr_range constituents[];
};

#define FFA_RET_SUCCESS 0
#define FFA_RET_INVALID_PARAMETERS 2

/* same semantics as target include/linux/overflow.h check_add_overflow */
static int ovf_add_u32(u32 a, unsigned long b, u32 *d)
{
    return __builtin_add_overflow(a, b, d);
}

/* post-fix guard */
static int new_guard(u32 offset, u32 fraglen, u32 *checked_out, long *nr_out)
{
    u32 checked_offset;
    if (ovf_add_u32(offset, sizeof(struct ffa_composite_mem_region), &checked_offset))
        return FFA_RET_INVALID_PARAMETERS;
    if (checked_out)
        *checked_out = checked_offset;
    if (fraglen < checked_offset)
        return FFA_RET_INVALID_PARAMETERS;
    if (nr_out)
        *nr_out = (long)fraglen - ((long)offset + (long)sizeof(struct ffa_composite_mem_region));
    return FFA_RET_SUCCESS;
}

/* pre-fix guard as written in target line 463 */
static int old_guard(u32 offset, u32 fraglen)
{
    if (fraglen < offset + sizeof(struct ffa_composite_mem_region))
        return FFA_RET_INVALID_PARAMETERS;
    return FFA_RET_SUCCESS;
}

/* bound if the addition had been evaluated with 32-bit wrap (upstream's premise) */
static u32 old_bound_u32_wrapped(u32 offset)
{
    return (u32)(offset + (u32)sizeof(struct ffa_composite_mem_region));
}

int main(void)
{
    int fails = 0;
    u32 checked = 0;
    long nr = -1;
    int rc;

    printf("sizeof(struct ffa_composite_mem_region)=%zu sizeof(addr_range)=%zu\n",
           sizeof(struct ffa_composite_mem_region), sizeof(struct ffa_mem_region_addr_range));

    /* positive path: offset inside fragment, room for header + 3 constituents */
    rc = new_guard(0x40, 0x80, &checked, &nr);
    printf("positive offset=0x40 fraglen=0x80 -> rc=%d checked=0x%x nr=%ld\n", rc, checked, nr);
    if (rc != FFA_RET_SUCCESS || checked != 0x50 || nr != 0x30 || (nr % 16) != 0)
        fails++;

    /* negative: exact wrap range start [U32_MAX-15 .. U32_MAX] */
    rc = new_guard(0xFFFFFFF0u, 0x40, &checked, &nr);
    printf("negative offset=0xFFFFFFF0 fraglen=0x40 -> rc=%d\n", rc);
    if (rc != FFA_RET_INVALID_PARAMETERS)
        fails++;
    rc = new_guard(0xFFFFFFFFu, 0x40, &checked, &nr);
    printf("negative offset=0xFFFFFFFF fraglen=0x40 -> rc=%d\n", rc);
    if (rc != FFA_RET_INVALID_PARAMETERS)
        fails++;

    /* boundary: no wrap but still beyond fraglen -> reject by bound check */
    rc = new_guard(0xFFFFFFE0u, 0x40, &checked, &nr);
    printf("boundary offset=0xFFFFFFE0 fraglen=0x40 -> rc=%d checked=0x%x\n", rc, checked);
    if (rc != FFA_RET_INVALID_PARAMETERS)
        fails++;

    /* boundary: accepted iff offset+sizeof <= fraglen */
    rc = new_guard(0x30, 0x40, &checked, &nr);
    printf("boundary offset=0x30 fraglen=0x40 -> rc=%d checked=0x%x nr=%ld\n", rc, checked, nr);
    if (rc != FFA_RET_SUCCESS || nr != 0)
        fails++;
    rc = new_guard(0x31, 0x40, &checked, &nr);
    printf("boundary offset=0x31 fraglen=0x40 -> rc=%d\n", rc);
    if (rc != FFA_RET_INVALID_PARAMETERS)
        fails++;

    /* demonstrate the upstream premise: 32-bit bound wraps to a small value */
    u32 wrapped = old_bound_u32_wrapped(0xFFFFFFF0u);
    printf("32-bit-wrapped bound for 0xFFFFFFF0 = 0x%x (would pass fraglen=0x40: %d)\n",
           wrapped, (0x40 < wrapped));
    if (!(wrapped == 0x0 && (0x40 < wrapped) == 0))
        fails++;

    /* LP64 observation: the literal pre-fix expression already rejects on LP64 */
    printf("LP64 old_guard(0xFFFFFFF0,0x40)=%d (informational)\n", old_guard(0xFFFFFFF0u, 0x40));

    printf(fails ? "HARNESS FAILURES=%d\n" : "HARNESS OK\n", fails);
    return fails ? 1 : 0;
}
'''
c_path = WORK / "ffa_guard_test.c"
bin_path = WORK / "ffa_guard_test"
c_path.write_text(c_src)
comp = subprocess.run(["gcc", "-O2", "-Wall", "-Wextra", "-o", str(bin_path), str(c_path)],
                      capture_output=True, text=True)
print("gcc compile exit:", comp.returncode)
if comp.stderr.strip():
    print(comp.stderr.strip())
check(comp.returncode == 0, "C harness compiles with host gcc")
if comp.returncode == 0:
    run = subprocess.run([str(bin_path)], capture_output=True, text=True)
    print(run.stdout, end="")
    if run.stderr.strip():
        print(run.stderr.strip())
    check(run.returncode == 0, "C harness assertions pass")

print("gcc version:", subprocess.run(["gcc", "--version"], capture_output=True, text=True).stdout.splitlines()[0])
print("cwd:", os.getcwd())
if failures:
    print("REGRESSION_FAILED")
    sys.exit(1)
print("REGRESSION_PASSED")

